'use strict';
reports.push(['report-stock','Stock Verification Report']);titles['report-stock']='Stock Verification Report';
let stockSheet=null,stockSheetView='',stockVarianceFilter='all';
function newStockSheet(){return {id:'STOCK-'+Date.now(),asOf:new Date().toISOString(),lines:db.parts.map(p=>({part:p.id,name:p.name,category:p.category||'',make:p.vehicleMake||'',model:p.vehicleModel||'',rack:p.rack||'',unit:p.unit||'PCS',opening:Number(p.opening||0),system:stock(p.id),cost:Number(p.purchase||0),physical:null,note:''}))}}
function stockCountVariance(line){return line.physical===null?null:round(Number(line.physical)-Number(line.system))}
function stockReportSheet(){if(stockSheetView)return (db.stockCounts||[]).find(s=>s.id===stockSheetView)||null;if(!stockSheet)stockSheet=newStockSheet();return stockSheet}
function stockReportLines(sheet){return sheet.lines.filter(l=>matches(l)).filter(l=>{let v=stockCountVariance(l);return stockVarianceFilter==='all'||stockVarianceFilter==='shortage'&&v!==null&&v<0||stockVarianceFilter==='excess'&&v!==null&&v>0||stockVarianceFilter==='uncounted'&&v===null||stockVarianceFilter==='difference'&&v!==null&&v!==0})}
function stockCountTable(sheet,editable){return table(['Part / SKU','Part Name','Vehicle Make / Model','Rack','Unit','System Stock','Physical Count','Shortage / Excess','Value Difference','Count Note'],stockReportLines(sheet).map(l=>{let v=stockCountVariance(l);return [esc(l.part),esc(l.name),esc([l.make,l.model].filter(Boolean).join(' / ')||'—'),esc(l.rack||'—'),esc(l.unit),l.system,editable?`<input type="number" min="0" step="0.01" class="physicalCount" data-count-part="${esc(l.part)}" aria-label="Physical count for ${esc(l.name)}" value="${l.physical===null?'':l.physical}" placeholder="Not counted">`:l.physical===null?'Not counted':l.physical,`<span data-count-variance="${esc(l.part)}">${v===null?'Not counted':v<0?'Short '+Math.abs(v):v>0?'Excess '+v:'Matched'}</span>`,`<span data-count-value="${esc(l.part)}">${v===null?'—':money(v*l.cost)}</span>`,editable?`<input type="text" data-count-note="${esc(l.part)}" aria-label="Count note for ${esc(l.name)}" value="${esc(l.note)}" maxlength="300">`:esc(l.note||'—')]}))}
function stockCountSummary(sheet){let counted=sheet.lines.filter(l=>l.physical!==null),short=counted.filter(l=>stockCountVariance(l)<0),excess=counted.filter(l=>stockCountVariance(l)>0);return summary([['PARTS IN SHEET',sheet.lines.length],['COUNTED / UNCOUNTED',counted.length+' / '+(sheet.lines.length-counted.length)],['SHORTAGE VALUE (AT COST)',money(-short.reduce((s,l)=>s+stockCountVariance(l)*l.cost,0))],['EXCESS VALUE (AT COST)',money(excess.reduce((s,l)=>s+stockCountVariance(l)*l.cost,0))]])}
const reportBeforeStock=reportPage;
reportPage=function(){if(page!=='report-stock')return reportBeforeStock();let sheet=stockReportSheet();if(!sheet){stockSheetView='';sheet=stockReportSheet()}return `<div class="notice">Compare with a physical count to investigate differences. System stock includes parts reserved on saved job cards. A shortage is a difference to investigate, not proof of leakage. This sheet uses the stock snapshot from <strong>${esc(uiDateTime(sheet.asOf))}</strong>; avoid stock movements while counting. Saving counts does not adjust stock.</div><div id="stockCountSummary">${stockCountSummary(sheet)}</div><div class="toolbar"><input class="search" id="search" value="${esc(search)}" placeholder="Search part, SKU, make, model or rack" aria-label="Search stock report"><select id="stockCountHistory" aria-label="Stock count history"><option value="">Current unsaved count</option>${opts((db.stockCounts||[]).map(s=>({value:s.id,label:uiDateTime(s.savedAt)+' · '+s.id})),stockSheetView)}</select><select id="stockVarianceFilter" aria-label="Stock variance filter">${opts([{value:'all',label:'All parts'},{value:'difference',label:'Differences only'},{value:'shortage',label:'Shortages'},{value:'excess',label:'Excess stock'},{value:'uncounted',label:'Not counted'}],stockVarianceFilter)}</select><button type="button" class="btn secondary" id="newStockCount">New Count / Refresh Stock</button><button type="button" class="btn" id="saveStockCount" ${stockSheetView?'disabled':''}>Save Physical Count</button><button type="button" class="btn secondary" id="exportStockCount">Export Excel</button><button type="button" class="btn secondary" id="printStockCount">Print Report</button></div>${stockCountTable(sheet,!stockSheetView)}`};
const renderBeforeStock=render;
render=function(){renderBeforeStock();if(page!=='report-stock')return;$('#stockCountHistory').onchange=e=>{stockSheetView=e.target.value;render()};$('#stockVarianceFilter').onchange=e=>{stockVarianceFilter=e.target.value;render()};$('#newStockCount').onclick=()=>{if(stockSheet?.lines.some(l=>l.physical!==null)&&!window.confirm('Discard the unsaved count and take a fresh system-stock snapshot?'))return;stockSheet=newStockSheet();stockSheetView='';render()};$('#saveStockCount').onclick=()=>{let sheet=stockReportSheet();if(!sheet.lines.some(l=>l.physical!==null))return toast('Enter at least one physical count. Blank entries mean not counted.');let before=structuredClone(db);let saved={...structuredClone(sheet),savedAt:new Date().toISOString()};db.stockCounts=db.stockCounts||[];db.stockCounts.push(saved);audit('Stock Count',saved.id+' saved; stock unchanged');if(save('Physical count saved; inventory unchanged')===false){db=before;return}stockSheet=null;stockSheetView=saved.id;render()};$('#exportStockCount').onclick=()=>{let sheet=stockReportSheet(),rows=[['Count ID','Snapshot Time','Part / SKU','Part Name','Make','Model','Rack','Unit','System Stock','Physical Count','Variance','Value Difference at Cost','Note'],...stockReportLines(sheet).map(l=>{let v=stockCountVariance(l);return [sheet.id,sheet.asOf,l.part,l.name,l.make,l.model,l.rack,l.unit,l.system,l.physical===null?'Not counted':l.physical,v===null?'':v,v===null?'':round(v*l.cost),l.note]})];download('\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'BIKE-DOCTOR-stock-count-'+today()+'.csv','text/csv;charset=utf-8')};$('#printStockCount').onclick=()=>{let sheet=stockReportSheet();openModal('Stock Verification Report',`<div class="invoice"><h2>${esc(db.settings.name)} — Stock Verification</h2><p>Snapshot: ${esc(uiDateTime(sheet.asOf))} · ${esc(sheet.id)}</p><p>Variance = physical minus system stock. Blank counts are not counted. Stock is unchanged.</p>${stockCountTable(sheet,false)}</div><div class="formactions">${btn('Close','cancel','secondary')}<button type="button" id="printStockSheet" class="btn">Print A4 / Save PDF</button></div>`);$('#printStockSheet').onclick=printA4Invoice}};
document.addEventListener('input',e=>{if(page!=='report-stock'||stockSheetView)return;let id=e.target.dataset.countPart||e.target.dataset.countNote;if(!id)return;let sheet=stockReportSheet(),line=sheet.lines.find(l=>l.part===id);if(!line)return;if(e.target.dataset.countPart){let value=e.target.value;if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0)){e.target.setCustomValidity('Enter zero or a positive quantity');return}e.target.setCustomValidity('');line.physical=value===''?null:Number(value);let v=stockCountVariance(line);for(let element of $$('[data-count-variance]'))if(element.dataset.countVariance===id)element.textContent=v===null?'Not counted':v<0?'Short '+Math.abs(v):v>0?'Excess '+v:'Matched';for(let element of $$('[data-count-value]'))if(element.dataset.countValue===id)element.textContent=v===null?'—':money(v*line.cost);$('#stockCountSummary').innerHTML=stockCountSummary(sheet)}else line.note=e.target.value},true);
if(location.hash==='#report-stock'){page='report-stock';reportMenuOpen=true}render();

